function AUTH-PATH(h, t, p):        // p: list of booleans
    if t is Leaf:
        return []
    if head(p) = LEFT:
        return MERKLE-ROOT(h, t.right) :: AUTH-PATH(h, t.left, tail(p))
    else:                            // head(p) = RIGHT
        return MERKLE-ROOT(h, t.left) :: AUTH-PATH(h, t.right, tail(p))

