function RECONSTRUCT(h, x, p, cert):
    if p = []:
        return x
    sub <- RECONSTRUCT(h, x, tail(p), tail(cert))
    if head(p) = LEFT:
        return h(sub, head(cert))
    else:
        return h(head(cert), sub)

function VERIFY(h, leaf, p, cert, published_root):
    return RECONSTRUCT(h, leaf, p, cert) = published_root

function CHAIN(ts):                  // ts: list of proof trees
    if ts = []:
        return Leaf(0)
    if ts = [t]:
        return t
    return Node(head(ts), CHAIN(tail(ts)))

